def generate_color_code(n, p, palette):
    from itertools import product

    # Generate all possible n-bit binary strings
    all_strings = [''.join(p) for p in product('01', repeat=n)]

    # Function to calculate Hamming distance between two binary strings
    def hamming_distance(s1, s2):
        return sum(c1 != c2 for c1, c2 in zip(s1, s2))

    # Backtracking function to construct the color code
    def backtrack(path, used):
        if len(path) == 2**n:
            return path

        last_string = path[-1]
        for i in range(2**n):
            next_string = all_strings[i]
            if not used[i] and hamming_distance(last_string, next_string) in palette:
                used[i] = True
                result = backtrack(path + [next_string], used)
                if result:
                    return result
                used[i] = False

        return None

    # Try to find a valid color code starting from each string
    for i in range(2**n):
        used = [False] * 2**n
        used[i] = True
        result = backtrack([all_strings[i]], used)
        if result:
            return result

    return "impossible"

