def generate_color_code(n, p, palette):
    from itertools import product

    # Generate all possible n-bit binary strings
    all_strings = [''.join(p) for p in product('01', repeat=n)]

    # Function to calculate Hamming distance between two binary strings
    def hamming_distance(s1, s2):
        return sum(c1 != c2 for c1, c2 in zip(s1, s2))

    # Create a graph where each node is a string and edges exist between strings differing by one bit
    graph = {s: [] for s in all_strings}
    for s1 in all_strings:
        for s2 in all_strings:
            if hamming_distance(s1, s2) in palette:
                graph[s1].append(s2)

    # Try to find a Hamiltonian path in the graph
    def find_hamiltonian_path(path, visited):
        if len(path) == 2**n:
            return path

        last_node = path[-1]
        for neighbor in graph[last_node]:
            if neighbor not in visited:
                visited.add(neighbor)
                result = find_hamiltonian_path(path + [neighbor], visited)
                if result:
                    return result
                visited.remove(neighbor)

        return None

    # Start from any node and try to find a Hamiltonian path
    for start_node in all_strings:
        visited = {start_node}
        path = [start_node]
        result = find_hamiltonian_path(path, visited)
        if result:
            return result

    return "impossible"

